        final ForbidCertainMethodCheck check = new ForbidCertainMethodCheck();
        try {
            check.setArgumentCount("abc");
            Assert.fail("Expecting CheckstyleException");
        }
        catch (CheckstyleException ex) {
            Assert.assertTrue(ex.getMessage().contains("Specified range is not valid"));
        }
        catch (NumberFormatException ex) {
            Assert.fail("NumberFormatException should be wrapped in CheckstyleException, "
                + "but NumberFormatException was thrown directly: " + ex.getMessage());
        }
    }

